solutionCode:
pub struct Ponto {
    pub x: i32,
    pub y: i32,
    pub soma: i32,
}

pub fn ponto_de(x: i32, y: i32) -> Ponto {
    Ponto { x: x, y: y, soma: x + y }
}

testsCode:
use desafio::ponto_de;

#[test]
fn testa_o_y_do_ponto_dois_por_tres() {
    assert_eq!(ponto_de(2, 3).y, 3);
}

#[test]
fn testa_o_x_do_ponto_dois_por_tres() {
    assert_eq!(ponto_de(2, 3).x, 2);
}

#[test]
fn testa_a_soma_do_ponto_dois_por_tres() {
    assert_eq!(ponto_de(2, 3).soma, 5);
}

#[test]
fn testa_a_soma_do_ponto_negativo_quatro_por_cinco() {
    assert_eq!(ponto_de(-4, 5).soma, 1);
}
